from typing import *
from collections import *

class Solution:
    def distinctDifferenceArray(self, nums: List[int]) -> List[int]:
        pre = Counter(nums[:])
        suf = Counter(nums)
        res = []
        for i in range(len(nums)):
            res.append(len(pre) - len(suf))
            suf[nums[i]] -= 1
            if suf[nums[i]] == 0:
                del suf[nums[i]]
        return res

from heapq import heappush, heappop

class Solution:
    def matrixSum(self, nums: List[List[int]]) -> int:
        res = 0

        # Create a min heap for each row
        rows = [list(row) for row in nums]
        for i in range(len(rows)):
            heappush(rows[i], -row[0])

        while rows:
            max_val = -heappop(rows[0])
            res += max_val

            # Update the remaining numbers in the current row
            if rows[0]:
                heappush(rows[0], -rows[0][-1])
                rows[0].pop()

        return res

