class Solution:
    def sumOfPower(self, nums: List[int]) -> int:
        n = len(nums)
        prefix = [0] * (n+1)
        prefix[0] = 0
        for i in range(1,n+1):
            prefix[i] = prefix[i-1] + nums[i-1]

        ans = 0
        for i in range(n):
            ans += prefix[n-i]*prefix[i]**2

        return ans % (10**9 + 7)
